<?php
if(!current_user_can('chidemoon_manage_affiliate'))throw new RuntimeException('forbidden');
foreach([462,3977,295,298]as$id){$source=get_attached_file($id);$variants=[];foreach([480,768,1280]as$width){$editor=wp_get_image_editor($source);if(is_wp_error($editor))throw new RuntimeException($editor->get_error_message());$size=$editor->get_size();$actual=min($width,$size['width']);$editor->resize($actual,null,false);$editor->set_quality(80);$dest=dirname($source).'/'.pathinfo($source,PATHINFO_FILENAME).'-ch-look-'.$actual.'.webp';$r=$editor->save($dest,'image/webp');if(is_wp_error($r))throw new RuntimeException($r->get_error_message());$variants[$actual]=['url'=>dirname(wp_get_attachment_url($id)).'/'.basename($dest),'width'=>$r['width'],'height'=>$r['height'],'bytes'=>filesize($dest)];}update_post_meta($id,'_chidemoon_look_webp',$variants);echo wp_json_encode(['id'=>$id,'original'=>filesize($source),'variants'=>$variants])."\n";}
